macro_rules! deps {
    () => {
        ByteClasses!();
        NFA!();
        StateID!();
        SparseSet!();
        Epsilons!();
        DFA!();
        Config!();
    };
}

macro_rules! InternalBuilder {
    () => {
        deps!();
        # [doc = " An internal builder for encapsulating the state necessary to build a"] # [doc = " one-pass DFA. Typical use is just `InternalBuilder::new(..).build()`."] # [doc = ""] # [doc = " There is no separate pass for determining whether the NFA is one-pass or"] # [doc = " not. We just try to build the DFA. If during construction we discover that"] # [doc = " it is not one-pass, we bail out. This is likely to lead to some undesirable"] # [doc = " expense in some cases, so it might make sense to try an identify common"] # [doc = " patterns in the NFA that make it definitively not one-pass. That way, we"] # [doc = " can avoid ever trying to build a one-pass DFA in the first place. For"] # [doc = " example, '\\w*\\s' is not one-pass, and since '\\w' is Unicode-aware by"] # [doc = " default, it's probably not a trivial cost to try and build a one-pass DFA"] # [doc = " for it and then fail."] # [doc = ""] # [doc = " Note that some (immutable) fields are duplicated here. For example, the"] # [doc = " 'nfa' and 'classes' fields are both in the 'DFA'. They are the same thing,"] # [doc = " but we duplicate them because it makes composition easier below. Otherwise,"] # [doc = " since the borrow checker can't see through method calls, the mutable borrow"] # [doc = " we use to mutate the DFA winds up preventing borrowing from any other part"] # [doc = " of the DFA, even though we aren't mutating those parts. We only do this"] # [doc = " because the duplication is cheap."] # [derive (Debug)] struct InternalBuilder < 'a > { # [doc = " The DFA we're building."] dfa : DFA , # [doc = " An unordered collection of NFA state IDs that we haven't yet tried to"] # [doc = " build into a DFA state yet."] # [doc = ""] # [doc = " This collection does not ultimately wind up including every NFA state"] # [doc = " ID. Instead, each ID represents a \"start\" state for a sub-graph of the"] # [doc = " NFA. The set of NFA states we then use to build a DFA state consists"] # [doc = " of that \"start\" state and all states reachable from it via epsilon"] # [doc = " transitions."] uncompiled_nfa_ids : Vec < StateID > , # [doc = " A map from NFA state ID to DFA state ID. This is useful for easily"] # [doc = " determining whether an NFA state has been used as a \"starting\" point"] # [doc = " to build a DFA state yet. If it hasn't, then it is mapped to DEAD,"] # [doc = " and since DEAD is specially added and never corresponds to any NFA"] # [doc = " state, it follows that a mapping to DEAD implies the NFA state has"] # [doc = " no corresponding DFA state yet."] nfa_to_dfa_id : Vec < StateID > , # [doc = " A stack used to traverse the NFA states that make up a single DFA"] # [doc = " state. Traversal occurs until the stack is empty, and we only push to"] # [doc = " the stack when the state ID isn't in 'seen'. Actually, even more than"] # [doc = " that, if we try to push something on to this stack that is already in"] # [doc = " 'seen', then we bail out on construction completely, since it implies"] # [doc = " that the NFA is not one-pass."] stack : Vec < (StateID , Epsilons) > , # [doc = " The set of NFA states that we've visited via 'stack'."] seen : SparseSet , # [doc = " Whether a match NFA state has been observed while constructing a"] # [doc = " one-pass DFA state. Once a match state is seen, assuming we are using"] # [doc = " leftmost-first match semantics, then we don't add any more transitions"] # [doc = " to the DFA state we're building."] matched : bool , # [doc = " The config passed to the builder."] # [doc = ""] # [doc = " This is duplicated in dfa.config."] config : Config , # [doc = " The NFA we're building a one-pass DFA from."] # [doc = ""] # [doc = " This is duplicated in dfa.nfa."] nfa : & 'a NFA , # [doc = " The equivalence classes that make up the alphabet for this DFA>"] # [doc = ""] # [doc = " This is duplicated in dfa.classes."] classes : ByteClasses , }
    };
}

InternalBuilder!()